def format_args(args):
    """
    :param args:
        A list of arguments
    :type args:
        list
    :return:
        A string representation of those arguments
    :rtype:
        `unicode`
    """
    return u', '.join(format_arg(arg) for arg in args)


def format_call(call):
    """
    :param call:
        A call to a function
    :type call:
        dict
    :return:
        A string representation of that call
    :rtype:
        `unicode`
    """
    return u'{}({})'.format(call['function'], format_args(call['args']))


def format_call_list(call_list):
    """
    :param call_list:
        A list of calls to functions
    :type call_list:
        list
    :return:
        A string representation of those calls
    :rtype:
        `unicode`
    """
    return u'\n'.join(format_call(call) for call in call_list)


